package com.payroll.service; import com.payroll.model.Employee; import com.payroll.model.Payroll; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.LocalDate; import static org.junit.jupiter.api.Assertions.*; class PayrollCalculatorTest { @Test void calculatesExpectedSalaryComponents(){Employee e=new Employee("T-1","Test User","test@example.test","9000000000","Engineering","Developer",new BigDecimal("50000"),LocalDate.now());Payroll p=new Payroll();p.setEmployee(e);PayrollCalculator.calculate(p);assertEquals(new BigDecimal("10000.00"),p.getHra().setScale(2));assertEquals(new BigDecimal("67500.00"),p.getGrossSalary().setScale(2));assertEquals(new BigDecimal("54750.00"),p.getNetSalary().setScale(2));} }
